{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE c.name = \"Formação JavaScript Expert\" AND p.status = \"paid\" RETURN s.name AS studentName, s.email AS email, s.phone AS phone, p.paymentDate AS paymentDate ORDER BY p.paymentDate DESC"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE p.status = \"paid\" AND p.paymentMethod = \"credit card\" WITH SUM(p.amount) AS totalRevenue RETURN totalRevenue"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE p.status = \"paid\" WITH c, SUM(p.amount) AS revenue RETURN c.name AS courseName, revenue ORDER BY revenue DESC"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE p.status = \"paid\" WITH c, SUM(p.amount) AS revenue WITH collect(revenue) AS revs, size(revs) AS n WITH sort(revs) AS revs, n, min(revs) AS minRevenue, max(revs) AS maxRevenue WITH revs, n, minRevenue, maxRevenue, CASE WHEN n % 2 = 1 THEN revs[toInteger(n / 2)] ELSE (revs[toInteger(n / 2) - 1] + revs[toInteger(n / 2)]) / 2 END AS median, revs[toInteger(n / 4)] AS firstQuartile, revs[toInteger(3 * n / 4)] AS thirdQuartile RETURN minRevenue, maxRevenue, median, firstQuartile, thirdQuartile"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE p.status = \"paid\" WITH c, SUM(p.amount) AS revenue WITH collect(revenue) AS revenues, min(revenue) AS minRevenue, max(revenue) AS maxRevenue RETURN minRevenue, maxRevenue, percentileCont(0.5, revenues) AS medianRevenue, percentileCont(0.25, revenues) AS q1Revenue, percentileCont(0.75, revenues) AS q3Revenue"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE p.status = \"paid\" WITH c, SUM(p.amount) AS revenue WITH MIN(revenue) AS minRevenue, MAX(revenue) AS maxRevenue, collect(revenue) AS revenues WITH minRevenue, maxRevenue, revenues, apoc.math.quantiles(revenues, [0.25, 0.75]) AS qList RETURN minRevenue, maxRevenue, apoc.math.median(revenues) AS medianRevenue, qList[0] AS q1, qList[1] AS q3"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course) WHERE p.status = \"paid\" WITH p.paymentMethod AS method, COUNT(*) AS purchaseCount ORDER BY purchaseCount DESC RETURN method AS paymentMethod, purchaseCount"
}

{
  "query": "MATCH (s:Student)-[pr:PROGRESS]->(c:Course) RETURN DISTINCT s.id AS studentId, s.name AS studentName, c.name AS courseName, pr.progress AS progress ORDER BY s.id, c.name"
}

{
  "query": "MATCH (s:Student)-[pr:PROGRESS]->(c:Course) WHERE NOT EXISTS { MATCH (s)-[p:PURCHASED]->(c) WHERE p.status = \"paid\" } RETURN s.name AS studentName, s.email AS studentEmail, c.name AS courseName ORDER BY s.name NULLS LAST"
}

{
  "query": "MATCH (s:Student)-[pr:PROGRESS]->(c:Course)
WHERE NOT EXISTS { MATCH (s)-[:PURCHASED]->(c) }
RETURN s.name AS studentName, s.email AS email, s.phone AS phone, c.name AS courseName, c.url AS url
ORDER BY studentName, courseName"
}

{
  "query": "MATCH (s:Student)-[p:PURCHASED]->(c:Course)
WHERE p.status = "paid" AND NOT EXISTS { MATCH (s)-[:PROGRESS]->(c) }
RETURN s.name AS studentName, s.email AS email, s.phone AS phone, c.name AS courseName, c.url AS courseUrl
ORDER BY s.name"
}
